 v=pd.DataFrame(rows);g=pd.DataFrame(meta.values()).sort_values('candidate_id');ids=g.candidate_id.tolist();w=v.pivot(index='model_id',columns='candidate_id',values='value').reindex(index=models,columns=ids);old={z:q.set_index('model_id').reindex(models).value.to_numpy(float) for z,q in xreg.groupby('candidate_id')};cross=pd.DataFrame([dict(candidate_id=z,existing_candidate_id=o,**rel(w[z].to_numpy(float),a),evidence_scope='full58_x_only',selection_effect='none') for z in ids for o,a in old.items()]);inter=pd.DataFrame([dict(left_candidate_id=a,right_candidate_id=b,**rel(w[a].to_numpy(float),w[b].to_numpy(float)),evidence_scope='full58_x_only',selection_effect='none') for n,a in enumerate(ids) for b in ids[n+1:]]);coll=pd.DataFrame([dict(pair_id=q,candidate_id=z,absolute_delta=abs(float(w.loc[a,z])-float(w.loc[b,z]))) for a,b,q in [('T8','T9','T8_T9'),('T5','T6','T5_T6')] for z in ids])
 for suffix,data in {'candidate_registry':g,'values_long':v,'values_wide':w.reset_index(),'vs_XREG_v1_5_redundancy':cross,'internal_redundancy':inter,'collision_diagnostic':coll}.items():data.to_csv(T/f'PRM126_overlay_component_density_{suffix}.csv',index=False,encoding='utf-8-sig')
 qa=pd.DataFrame([dict(check_id='P126-01',status='PASS' if len(g)==24 and len(v)==1392 and np.isfinite(v.value).all() and len(cross)==24*365 and len(inter)==276 else 'FAIL',detail='scope and no-y output')]);qa.to_csv(F/'PRM126_producer_QA.csv',index=False,encoding='utf-8-sig');print(qa.to_dict('records'))
 if not qa.status.eq('PASS').all():raise SystemExit(1)
